stylesInline:
#project-modules .title { color: #3B3B3B;font-family: arial,helvetica,sans-serif;font-size: 16px;font-style: normal;font-weight: bold;line-height: 1.4em;text-align: left;text-decoration: none; }
#project-modules .sub-title { color: #3B3B3B;font-family: arial,helvetica,sans-serif;font-size: 14px;font-style: normal;font-weight: normal;line-height: 1.4em;text-align: left;text-decoration: none; }
#project-modules .editor-text .main-text, #primary-project-content.project-styles .main-text { color: #3B3B3B;font-family: arial,helvetica,sans-serif;font-size: 12px;font-style: normal;font-weight: normal;line-height: 1.4em;text-align: left;text-decoration: none; }
#project-modules .caption, #project-modules .caption-text-wrap { color: #3B3B3B;font-family: arial,helvetica,sans-serif;font-size: 11px;font-style: italic;font-weight: normal;line-height: 1.4em;text-align: left;text-decoration: none; }
#project-modules .caption-text-wrap a { font-size: 11px !important; }
#project-modules .main-text a { color: #1769FF;text-align: left;text-decoration: none; }
#primary-project-content .module { padding-bottom: 0px; }
#primary-project-content { padding-top: 50px; background-color: #FFFFFF;  }
.spacer { height: 20px; }.divider { display: none; }.module.last .divider { display: none; }
